import{_ as d,o as a,c as e,a7 as r}from"./chunks/framework.BCbKzsgW.js";const m=JSON.parse('{"title":"业务场景与批量设计","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/scenarios/batch-design.md","filePath":"development/common/task-scheduling/scenarios/batch-design.md","lastUpdated":1793441194000}'),i={name:"development/common/task-scheduling/scenarios/batch-design.md"};function n(h,t,o,l,u,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ye-wu-chang-jing-yu-pi-liang-she-ji" tabindex="-1">业务场景与批量设计 <a class="header-anchor" href="#ye-wu-chang-jing-yu-pi-liang-she-ji" aria-label="Permalink to &quot;业务场景与批量设计&quot;">​</a></h1><p>后台任务的实现从业务规则开始：什么事实触发动作，动作最晚什么时候完成，重复执行会产生什么后果，以及谁负责判断最终结果。相同的队列和重试机制，在会员到期、视频转码和库存提醒中需要不同的业务约束。</p><p>下面各篇采用明确的示例规则分析实现，不代表所有产品都采用相同政策。扫描间隔、批次大小、并发数和发送速率都是容量设计样例，需要结合自己的时效和下游限制确定。</p><h2 id="cong-xu-qiu-dao-shi-xian-xu-yao-que-ding-shi-me" tabindex="-1">从需求到实现需要确定什么 <a class="header-anchor" href="#cong-xu-qiu-dao-shi-xian-xu-yao-que-ding-shi-me" aria-label="Permalink to &quot;从需求到实现需要确定什么&quot;">​</a></h2><p>每个场景都需要落实下面的决策，代码里的表、接口和任务应能对应到这些业务约束。</p><table tabindex="0"><thead><tr><th>决策</th><th>需要给出的具体答案</th><th>开发落点</th></tr></thead><tbody><tr><td>业务目标</td><td>服务谁，什么结果才算完成</td><td>业务状态和用户可见结果</td></tr><tr><td>时间语义</td><td>什么时候生效，最晚什么时候完成</td><td>期限、数据窗口、任务截止时间</td></tr><tr><td>触发入口</td><td>请求、事件、扫描分别承担什么</td><td>API、事件接收器、调度计划</td></tr><tr><td>事实来源</td><td>业务表、外部渠道、指标系统谁说了算</td><td>查询与核对接口</td></tr><tr><td>数据身份</td><td>同一业务动作如何识别</td><td>主键、业务键、周期与版本</td></tr><tr><td>并发约束</td><td>两个请求或 Worker 同时处理怎么办</td><td>条件更新、唯一约束、事务边界</td></tr><tr><td>批量与容量</td><td>按什么单位拆分，瓶颈在哪里</td><td>分页、检查点、资源池和限速</td></tr><tr><td>通知语义</td><td>提醒谁，是否合并，什么情况下停止</td><td>通知意图、渠道记录、过期判断</td></tr><tr><td>故障恢复</td><td>哪一步可重试，哪里需要查询或人工处理</td><td>租约、重试、死信、对账</td></tr><tr><td>验收依据</td><td>如何证明正常与异常路径满足需求</td><td>业务结果断言、日志和指标</td></tr></tbody></table><p>各篇中的数据结构是设计所需的最小字段集合，SQL 展示关键约束，伪代码描述事务与处理顺序。它们尚未组成可运行的业务项目，也没有连接真实数据库或外部渠道执行。</p><h2 id="gong-yong-zhi-xing-yu-tong-zhi-yue-ding" tabindex="-1">共用执行与通知约定 <a class="header-anchor" href="#gong-yong-zhi-xing-yu-tong-zhi-yue-ding" aria-label="Permalink to &quot;共用执行与通知约定&quot;">​</a></h2><p>业务处理器可以复用<a href="./../implementation/database-queue.html">数据库任务队列</a>的领取、租约和尝试模型，但每次执行仍要读取业务当前状态。任务 ID 表示执行记录，业务键表示同一个业务动作，不能相互替代。</p><p>通知也需要两层记录：</p><table tabindex="0"><thead><tr><th>记录</th><th>最小字段与约束</th></tr></thead><tbody><tr><td>通知意图</td><td><code>intent_id</code>、业务对象、业务版本、提醒阶段、内容模板版本；逻辑键唯一</td></tr><tr><td>渠道投递</td><td><code>intent_id</code>、渠道、目标标识、状态、尝试次数、渠道请求 ID；按目标去重</td></tr></tbody></table><p>通知状态可以区分 pending、submitted、delivered、failed 和 suppressed；是否有 delivered 取决于渠道是否提供可信回执。每次重试检查通知是否仍有价值、用户是否仍允许该渠道，并沿用原始业务幂等键。</p><p>所有业务 API 都需要校验调用者和对象所属范围。示例中的内部重放、重跑、规则修改接口需要相应操作权限与审计记录，不因它们是后台接口就跳过鉴权。</p><h2 id="cong-an-li-zhong-ti-qu-ke-yi-fu-yong-de-pan-duan" tabindex="-1">从案例中提取可以复用的判断 <a class="header-anchor" href="#cong-an-li-zhong-ti-qu-ke-yi-fu-yong-de-pan-duan" aria-label="Permalink to &quot;从案例中提取可以复用的判断&quot;">​</a></h2><p>各篇先用一个具体需求比较候选方案，用时序图展示参与者、调用与关键分支，再用同一业务对象的记录变化解释正常与故障路径。时间、ID 和数量都是推演样例，不是实际运行日志。</p><p>时序图从上往下表示先后，横向生命线表示参与者；实线箭头表示请求或处理动作，虚线箭头表示响应。alt 表示互斥分支，opt 表示可选路径，loop 表示重复处理，par 表示可能交错的并发路径。一个图中合并展示的 Worker，在实现中可以拆为领取、业务处理与通知发送等独立组件。</p><p>迁移到自己的项目时，先保留业务必须成立的约束，再调整组件和容量。下面这些约束相似，但实现对象不同：</p><table tabindex="0"><thead><tr><th>场景</th><th>优先守住的约束</th><th>因此需要的机制</th></tr></thead><tbody><tr><td>会员</td><td>不因后台整理延迟而多授权</td><td>访问时核对期限，后台整理与通知分开</td></tr><tr><td>订单</td><td>同一订单不能同时有效支付和关闭</td><td>条件状态转换，渠道结果另行核对</td></tr><tr><td>预约</td><td>名额不超卖，改期失败不丢原预约</td><td>占位事务、请求幂等和预约版本</td></tr><tr><td>报表</td><td>用户不能看到半份或混合版本结果</td><td>固定输入身份、分片去重、完整后发布</td></tr><tr><td>对账</td><td>未取得完整事实不能启动错误补偿</td><td>采集检查点、完整性标记和证据复核</td></tr><tr><td>库存</td><td>高频变化不能产生无限告警或采购</td><td>当前状态、告警轮次、采购身份</td></tr><tr><td>监控</td><td>需要区分故障、通知和人工响应</td><td>规则状态、通知阶段和确认记录</td></tr><tr><td>文件</td><td>旧处理不能覆盖新文件的正式产物</td><td>源版本、处理版本和条件发布</td></tr><tr><td>物流</td><td>迟到消息不能随意覆盖当前事实</td><td>原始事件、归并规则和状态版本</td></tr><tr><td>清理</td><td>已失效不等于已删除，旧候选不能误删新对象</td><td>请求校验、执行前复核和对象版本</td></tr></tbody></table><p>增加一个字段时，应能说明它参与哪个判断。例如 version 应指出是哪种变化递增、哪个旧操作因此退出；只加字段而不在更新条件里使用，不会自动获得并发保护。</p><p>同样，选择队列之前先定位故障窗口：业务已经提交、动作却没保存，还是动作已完成、确认却丢失。前者需要可靠保存待办意图，后者需要识别重复结果；两者都叫“失败”，恢复方式却不同。</p><h2 id="chang-jing-ru-kou" tabindex="-1">场景入口 <a class="header-anchor" href="#chang-jing-ru-kou" aria-label="Permalink to &quot;场景入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>应该由什么触发</th><th>批量处理时的关键点</th></tr></thead><tbody><tr><td><a href="./order-timeout.html">电商订单</a></td><td>创建延迟检查任务，到期时重新判断</td><td>逐订单条件更新，支付与关闭竞争</td></tr><tr><td><a href="./membership.html">会员订阅</a></td><td>请求校验、到期扫描或延迟任务、续费事件配合</td><td>分离权益、状态更新与限速通知</td></tr><tr><td><a href="./appointments.html">预约提醒</a></td><td>预约确认、改期和开始前的提醒时间</td><td>按预约版本和参与人拆分，错过时效后跳过</td></tr><tr><td><a href="./reports.html">报表统计</a></td><td>固定周期和明确的数据窗口</td><td>按租户或分区计算，完整后发布</td></tr><tr><td><a href="./reconciliation.html">支付对账</a></td><td>账单可用或周期拉取</td><td>分页落原始流水，再匹配和处理差异</td></tr><tr><td><a href="./inventory.html">库存补货提醒</a></td><td>库存变化与兜底扫描</td><td>同一 SKU 的变化聚合，按告警轮次去重</td></tr><tr><td><a href="./monitoring.html">系统监控</a></td><td>指标采集、规则评估和状态变化</td><td>根因分组与抑制，避免千条告警同时通知</td></tr><tr><td><a href="./file-processing.html">文件异步处理</a></td><td>文件完成上传并通过校验</td><td>按资源成本限并发，部分失败独立重试</td></tr><tr><td><a href="./logistics.html">物流通知</a></td><td>承运商回调与状态补查</td><td>原始事件去重、状态归并、通知分发</td></tr><tr><td><a href="./data-maintenance.html">数据维护</a></td><td>保存到期时间并周期清理</td><td>过期即拒绝使用，物理回收分批进行</td></tr></tbody></table><h2 id="guo-nei-gong-kai-zi-liao-yu-ben-wen-she-ji-de-dui-ying-guan-xi" tabindex="-1">国内公开资料与本文设计的对应关系 <a class="header-anchor" href="#guo-nei-gong-kai-zi-liao-yu-ben-wen-she-ji-de-dui-ying-guan-xi" aria-label="Permalink to &quot;国内公开资料与本文设计的对应关系&quot;">​</a></h2><p>以下资料核对于 2026 年 10 月 29 日。团队技术文章、产品规则和开放接口文档提供的证据不同：团队文章说明特定时期的建设经验，产品文档说明外部行为或接入约束，社区文章还要辨认作者与原始出处。各篇区分来源明确描述的内容与本文据此提出的实现建议；本文的 SQL、时序图及 1000 个对象的推演仍是教学示例。</p><table tabindex="0"><thead><tr><th>场景</th><th>国内资料及性质</th><th>结合正文关注什么</th></tr></thead><tbody><tr><td><a href="./order-timeout.html#a-li-yun-ding-shi-xiao-xi-fang-an-zhong-de-ye-wu-bian-jie">订单超时</a></td><td>阿里云 RocketMQ 官方接入说明</td><td>定时消息不能撤回，付款后如何处理旧检查</td></tr><tr><td><a href="./membership.html#cong-a-li-yun-xu-fei-tong-zhi-kan-ti-xing-jie-duan-yu-fu-wu-zhuang-tai">会员订阅</a></td><td>阿里云 ECS、RocketMQ 真实产品规则</td><td>提醒阶段、权益结束与数据保留分别定义</td></tr><tr><td><a href="./appointments.html#teng-xun-hui-yi-ji-cheng-fang-an-zhong-de-chong-fu-tong-zhi-ru-kou">预约提醒</a></td><td>腾讯会议官方集成方案</td><td>API 与回调汇入统一通知入口，区分单次与系列预约</td></tr><tr><td><a href="./reports.html#schedulerx-pao-pi-mo-xing-yu-bao-biao-fa-bu-tiao-jian">报表统计</a></td><td>阿里云开发者社区方案、SchedulerX 官方文档</td><td>重复子任务与失败后汇总，不能直接发布半份结果</td></tr><tr><td><a href="./reconciliation.html#mei-tuan-pei-song-dui-zhang-ti-xi-zhong-de-er-ci-he-dui">支付对账</a></td><td>美团技术团队历史建设实践</td><td>明细与总数核对、差异复核及自动或人工处置</td></tr><tr><td><a href="./inventory.html#tao-bao-kai-fang-ping-tai-de-di-ku-cun-shi-jian-bao-han-shi-me">库存管理</a></td><td>淘宝开放平台事件协议</td><td>仓库与 SKU 维度、外部事件身份、订阅权限</td></tr><tr><td><a href="./monitoring.html#teng-xun-yun-gao-jing-shou-lian-de-fen-zu-yu-deng-dai-chuang-kou">系统监控</a></td><td>腾讯云可观测平台官方产品方案</td><td>收敛字段、首次等待与通知频率的时效代价</td></tr><tr><td><a href="./file-processing.html#teng-xun-yun-mei-ti-fu-wu-de-hui-diao-yu-jie-guo-bu-cha">文件处理</a></td><td>腾讯云点播、媒体处理官方接入说明</td><td>区分任务积压和回调缺失，按任务 ID 补查</td></tr><tr><td><a href="./logistics.html#kuai-di-100jie-ru-shuo-ming-zhong-de-ding-yue-zhuang-tai">物流通知</a></td><td>快递100API 在腾讯云社区的历史接入经验</td><td>订阅状态与运输状态分开，确认接收与重推分开</td></tr><tr><td><a href="./data-maintenance.html#a-li-yun-oss-sheng-ming-zhou-qi-yu-ye-wu-hui-shou-de-fen-gong">数据维护</a></td><td>阿里云 OSS 官方产品说明</td><td>周期回收与即时失效分工，注意配置覆盖语义</td></tr></tbody></table><p>原文链接和具体分析放在各篇对应章节与参考资料中。没有公开完整生产实现的场景，保留这一证据边界，不将产品功能介绍改写为某团队的生产复盘。</p><p>同一场景还可以比较不同厂商解决问题的位置。例如报表同时涉及 SchedulerX 的分片与重刷、FlowX 的业务日期依赖与配额；文件处理则结合腾讯云的结果补查、火山引擎的元信息就绪问题，以及美团流水线的领取确认与恢复设计。各篇在上述章节之后继续展开这些资料。</p><table tabindex="0"><thead><tr><th>厂商或团队</th><th>本专题补充分析的位置</th><th>值得对照的工程问题</th></tr></thead><tbody><tr><td>阿里</td><td><a href="./inventory.html">库存</a>、<a href="./reports.html">报表</a>、<a href="./logistics.html">物流</a>、<a href="./../implementation/observability.html">可观测性</a></td><td>TCC 迟到预留、历史数据重刷、事件流死信、失败分片追踪</td></tr><tr><td>腾讯</td><td><a href="./membership.html">会员</a>、<a href="./order-timeout.html">订单</a>、<a href="./appointments.html">预约</a></td><td>扫描与渠道回调解耦、延迟消息空洞、回调确认与重试</td></tr><tr><td>火山引擎</td><td><a href="./reports.html">报表</a>、<a href="./file-processing.html">文件</a>、<a href="./monitoring.html">监控</a>、<a href="./data-maintenance.html">清理</a></td><td>FlowX 的依赖与资源门槛、元信息尚未就绪、事件轮次、对象版本清理</td></tr><tr><td>美团</td><td><a href="./reconciliation.html">对账</a>、<a href="./file-processing.html">文件</a>、<a href="./monitoring.html">监控</a>、<a href="./logistics.html">物流</a>、<a href="./data-maintenance.html">清理</a></td><td>明细与汇总解耦、Worker 领取竞争、事件证据、分区同步、巡检治理闭环</td></tr></tbody></table><p>跨场景借鉴时需保留原场景的条件：CI/CD 作业的领取协议可以启发转码恢复设计，但不证明外部转码服务能被相同方式取消；结算平台接受中间汇总延迟，也不代表最终付款允许使用不完整数据。</p><h2 id="qing-qiu-jian-chashi-jian-he-shi-jian-ren-wu-zen-yang-pei-he" tabindex="-1">请求检查、事件和时间任务怎样配合 <a class="header-anchor" href="#qing-qiu-jian-chashi-jian-he-shi-jian-ren-wu-zen-yang-pei-he" aria-label="Permalink to &quot;请求检查、事件和时间任务怎样配合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>负责什么</th><th>单独使用会漏掉什么</th></tr></thead><tbody><tr><td>用户请求</td><td>当次访问的权限和最新页面状态</td><td>不登录、不访问的人</td></tr><tr><td>业务事件</td><td>及时接续付款、上传、发货等变化</td><td>仅因时间流逝而到期的对象</td></tr><tr><td>到期任务或扫描</td><td>提醒、过期转换、历史修复</td><td>不能代替访问时的授权判断</td></tr><tr><td>对账或兜底扫描</td><td>发现缺事件、缺任务、状态差异</td><td>可能晚于实时路径，必须有时效约束</td></tr></tbody></table><p>业务读取时就能根据期限判断的结果，不必等待批处理改完状态才生效。物理清理与用户通知则可以按各自的时效异步推进。</p><h2 id="pi-liang-de-si-zhong-li-du" tabindex="-1">批量的四种粒度 <a class="header-anchor" href="#pi-liang-de-si-zhong-li-du" aria-label="Permalink to &quot;批量的四种粒度&quot;">​</a></h2><p>“1000 个用户同一天到期”不等于建立一个包含 1000 人的巨型任务。通常需要区分：</p><ol><li>发现批次：扫描器一页读取多少候选，例如 100 条。</li><li>业务动作：每个会员周期、订单或文件独立判断和保存结果。</li><li>执行并发：Worker 同时处理多少动作，受数据库与下游容量限制。</li><li>通知分发：每人、每渠道保存发送结果，并按供应商配额限速。</li></ol><p>一次读取 100 条，不代表同时发起 100 个外部请求。一个人处理失败，也不应导致已经成功的其他 99 人重新接收通知。</p><h2 id="tong-zhi-jie-guo-xu-yao-dan-du-ji-lu" tabindex="-1">通知结果需要单独记录 <a class="header-anchor" href="#tong-zhi-jie-guo-xu-yao-dan-du-ji-lu" aria-label="Permalink to &quot;通知结果需要单独记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>能证明什么</th></tr></thead><tbody><tr><td>生成通知意图</td><td>业务决定需要提醒，内容与对象可追踪</td></tr><tr><td>渠道接受请求</td><td>邮件、短信或推送服务接受提交</td></tr><tr><td>回执报告送达</td><td>渠道提供了它定义的送达结果</td></tr><tr><td>用户已读或已操作</td><td>产品获得明确的用户行为</td></tr></tbody></table><p>对推送服务的成功响应，不能直接记作“用户已经看到”。通知失败不应让已经完成的订单关闭或会员状态变更回滚。</p><p>邮件服务的实际容量也有不同维度。例如 SES 同时限制滚动 24 小时发送量和每秒接收速率，见<a href="https://docs.aws.amazon.com/ses/latest/dg/manage-sending-quotas.html" target="_blank" rel="noreferrer">发送配额说明</a>。批处理需要同时核对这些限制。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Amazon SES：<a href="https://docs.aws.amazon.com/ses/latest/dg/manage-sending-quotas.html" target="_blank" rel="noreferrer">Managing sending limits</a></li></ul>',42)])])}const p=d(i,[["render",n]]);export{m as __pageData,p as default};
